<?php require __DIR__.'/includes/bootstrap.php';require_permission('users.manage');$pageTitle='Users';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$role=$_POST['role']??'user';$password=(string)($_POST['password']??'');if($name===''||!$email)throw new RuntimeException('Name and valid email are required.');if(!in_array($role,['admin','user'],true))throw new RuntimeException('Only Admin and User roles can be created here.');if(current_user()['role']==='admin'&&$role!=='user')throw new RuntimeException('Admins can only create users.');if(!$id&&strlen($password)<12)throw new RuntimeException('Initial password must be at least 12 characters.');if($id){if($password!==''){if(strlen($password)<12)throw new RuntimeException('Password must be at least 12 characters.');$s=db()->prepare('UPDATE users SET name=?,email=?,role=?,password_hash=? WHERE id=?');$s->execute([$name,$email,$role,password_hash($password,PASSWORD_DEFAULT),$id]);}else{db()->prepare('UPDATE users SET name=?,email=?,role=? WHERE id=?')->execute([$name,$email,$role,$id]);}}else{$s=db()->prepare('INSERT INTO users(name,email,password_hash,role,is_active,created_at) VALUES(?,?,?,?,1,NOW())');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);$id=(int)db()->lastInsertId();}flash('success','User saved.');audit('user_saved','user_id='.$id);redirect('users.php');}elseif($action==='toggle'){$id=(int)$_POST['id'];if($id===(int)current_user()['id'])throw new RuntimeException('You cannot deactivate your own account.');if(current_user()['role']==='admin')db()->prepare("UPDATE users SET is_active=0 WHERE id=? AND role='user'")->execute([$id]);else db()->prepare('UPDATE users SET is_active=IF(is_active=1,0,1) WHERE id=? AND role<>\'super_admin\'')->execute([$id]);flash('success','User status updated.');redirect('users.php');}}catch(Throwable $e){$error=$e->getMessage();}}$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT id,name,email,role,is_active FROM users WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;if($edit&&current_user()['role']==='admin'&&$edit['role']!=='user')$edit=null;}$users=current_user()['role']==='super_admin'?db()->query('SELECT id,name,email,role,is_active FROM users ORDER BY name')->fetchAll():db()->query("SELECT id,name,email,role,is_active FROM users WHERE role='user' ORDER BY name")->fetchAll();require __DIR__.'/includes/header.php';?><h1>User Management</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel"><h2><?=$edit?'Edit user':'Add user'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="field"><label>Name</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>Email</label><input type="email" name="email" required value="<?=e($edit['email']??'')?>"></div><div class="field"><label>Role</label><select name="role"><option value="user" <?=($edit['role']??'user')==='user'?'selected':''?>>User</option><?php if(current_user()['role']==='super_admin'):?><option value="admin" <?=($edit['role']??'')==='admin'?'selected':''?>>Admin</option><?php endif;?></select></div><div class="field"><label><?=$edit?'New password (leave blank to keep current)':'Initial password (minimum 12 characters)'?></label><input type="password" name="password" <?=$edit?'':'required minlength="12"'?> autocomplete="new-password"></div><button>Save user</button></form></section><section class="panel"><h2>Users</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=$u['is_active']?'Active':'Inactive'?></td><td><a href="users.php?edit=<?=(int)$u['id']?>">Edit</a> <?php if($u['role']!=='super_admin'):?><form method="post" class="inline"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><button class="secondary"><?=$u['is_active']?'Deactivate':'Activate'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php if(current_user()['role']==='super_admin'):?><section class="panel"><h2>Role permissions</h2><p>Super Admin always has all permissions. Select what Admin and User roles may do. User brand access is separately assigned in the database using <code>user_brands</code>.</p><form method="post" action="permissions.php"><?=csrf_field()?><div class="table-wrap"><table><thead><tr><th>Permission</th><th>Admin</th><th>User</th></tr></thead><tbody><?php foreach(['brands.manage'=>'Manage brands','users.manage'=>'Manage users','settings.manage'=>'Manage API settings'] as $key=>$label):?><tr><td><?=e($label)?></td><?php foreach(['admin','user'] as $role):$s=db()->prepare('SELECT allowed FROM permissions WHERE role=? AND permission_key=?');$s->execute([$role,$key]);?><td><input style="width:auto" type="checkbox" name="perm[<?=e($role)?>][<?=e($key)?>]" value="1" <?=$s->fetchColumn()?'checked':''?>></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><button>Save permissions</button></form></section><?php endif;?><?php require __DIR__.'/includes/footer.php'; ?>